import 'package:flutter/material.dart';

class UnsavedChangesGuard extends StatefulWidget {
  final Widget child;
  final bool Function() hasUnsavedChanges;
  final VoidCallback? onDiscard;
  final VoidCallback? onSave;
  final String? title;
  final String? message;
  final String? discardText;
  final String? saveText;
  final String? cancelText;

  const UnsavedChangesGuard({
    super.key,
    required this.child,
    required this.hasUnsavedChanges,
    this.onDiscard,
    this.onSave,
    this.title = 'Discard changes?',
    this.message = 'You have unsaved changes. Do you want to discard them?',
    this.discardText = 'Discard',
    this.saveText = 'Save',
    this.cancelText = 'Cancel',
  });

  @override
  State<UnsavedChangesGuard> createState() => _UnsavedChangesGuardState();
}

class _UnsavedChangesGuardState extends State<UnsavedChangesGuard> {
  @override
  Widget build(BuildContext context) {
    return WillPopScope(
      onWillPop: _onWillPop,
      child: widget.child,
    );
  }

  Future<bool> _onWillPop() async {
    if (!widget.hasUnsavedChanges()) {
      return true;
    }

    final result = await showDialog<bool>(
      context: context,
      barrierDismissible: false,
      builder: (context) {
        return AlertDialog(
          title: Text(widget.title ?? 'Discard changes?'),
          content: Text(widget.message ?? 'You have unsaved changes. Do you want to discard them?'),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(context).pop(false),
              child: Text(widget.cancelText ?? 'Cancel'),
            ),
            TextButton(
              onPressed: () => Navigator.of(context).pop(true),
              child: Text(widget.discardText ?? 'Discard'),
            ),
            if (widget.onSave != null)
              TextButton(
                onPressed: () => Navigator.of(context).pop(2),
                child: Text(widget.saveText ?? 'Save'),
              ),
          ],
        );
      },
    );

    if (result == 2) {
      widget.onSave?.call();
      return false;
    }

    if (result == true) {
      widget.onDiscard?.call();
      return true;
    }

    return false;
  }
}
